window.__posterData({"id": "hanna-dahl-clolien", "name": "Hanna Dahl Clolien", "folder": "Week1_Poster_Hanna_Dahl_Clolien_refactored", "v": "2", "scripts": ["https://cdn.jsdelivr.net/npm/p5@2.3.4/lib/p5.js", "https://cdn.jsdelivr.net/npm/p5.sound@0.4.1/dist/p5.sound.min.js"], "links": [], "css": "html, body {\n  margin: 0;\n  padding: 0;\n}\ncanvas {\n  display: block;\n}\n", "code": "// ACID VOID - interaktiv rave poster (refaktorerad)\n\n//=====================================================\n// ACID VOID - reflektion över AI-processen (steg 1-3)\n// Namn: Hanna Dahl Clolien\n//=====================================================\n\n// STEG 1: REFAKTORERING \n// (\"Refactor the code without changing functionality\")\n\n// Resultat: Postern såg ut och fungerade som tidigare. Originalet var 360 rader inklusive kommentarer och den refaktorerade versionen 180 rader. Utan kommentarer var skillnaden bara 7 rader, så den stora skillnaden beror främst på att mina långa förklarande kommentarer togs bort.\n\n// Det AI:n gjorde annorlunda:\n// - Konstanter (START_CIRCLES, MAX_CIRCLES, EXPLOSION_SIZE) istället för siffror direkt i koden. Här används också const, som jag inte hade använt tidigare.\n\n// - Hjälpfunktionen makeCircle(), som ersätter att skapa cirkelobjektet på två ställen, och drawTitle(), som ersätter fyra nästan identiska text()-rader. \n\n// - En while-loop i mousePressed() istället för if-satsen inne i loopen. Den tar bort de äldsta cirklarna tills det är max 150 kvar. Resultatet blir detsamma, men while-loopar har vi inte arbetat med på lektionerna.\n\n// - Kortare skrivsätt: ternär operator (villkor ? A : B) i färgfunktionerna samt += och -=. Det var nytt för mig och svårt i början, eftersom det skriver en villkorssats mer kompakt än if/else, och += ändrar ett värde direkt istället för att skriva ut hela beräkningen. Jag fick lägga extra tid på att koppla dem till skrivsätt jag redan kunde, och märkte att kortare kod inte nödvändigtvis är lättare att förstå.\n\n// STEG 2: MIN SPECIFIKA ÄNDRING (drawRings)\n\n// Jag bad AI:n ändra bara drawRings(): 16 ringar istället för 10, centrerade vid musen, med en hastighet på 0,5–4 pixlar per bildruta styrd av musens y-position. Ringarna skulle växla mellan mina befintliga färger och ha varierande linjetjocklek på 1–3 pixlar för att skapa djup. (Värdena justerade jag senare själv efter testning, se \"Egna justeringar efter testning\" längre ned.)\n\n// Resultat: Ringarna blev en \"portal\" som expanderar snabbare ju längre ned musen är. Tjockleken beräknas från ringens storlek, så små ringar blir tunna och stora ringar tjocka, vilket ger djupkänsla. \n\n// Det AI:n gjorde som jag inte själv hade tänkt på var att använda drawRings.phase för att spara ringarnas förflyttning mellan bildrutorna. Eftersom jag bad om att bara drawRings() skulle ändras löste AI:n det genom att spara värdet som en egenskap på själva funktionen, istället för som en global variabel utanför den. Värdet ökas med den aktuella hastigheten varje bildruta, vilket gör att rörelsen fortsätter mjukt när musens position ändras. Det här var nytt för mig, och jag förstår grundidén, men behöver undersöka tekniken mer för att förstå den helt.\n\n// Jag gillar resultatet eftersom en enkel upprepande animation har blivit en lysande, pulserande portal som passar acid-rave-estetiken. Den mest lyckade delen är att musrörelsen nu styr tempot, så att interaktiviteten blir en del av designen istället för något som bara finns där. Ringarna följer dessutom färgbytet mellan rosa och grönt eftersom de använder mina befintliga färgfunktioner, vilket gör att de hänger ihop med resten av affischen.\n\n// Jag valde medvetet att inte ändra färgerna och typsnittet (Impact), eftersom de är affischens identitet från vecka 42. Mina förändringar fokuserar på form och rörelse, medan färg och typografi håller ihop helheten. Ringarna kan dock konkurrera med titeln när animationen går snabbt, vilket jag återkommer till i designkritiken.\n\n// STEG 3: AI:ns EGET FÖRSLAG (neon-gnistor, drawSparks)\n// Jag bad AI:n göra steg 3 enligt uppgiften och lät den själv välja vilken funktion den ville lägga till. AI:n valde gnistor som sprutar ut från musen när man rör den. Ju snabbare musrörelse, desto fler gnistor (0-5 per bildruta). De växlar mellan temats två färger, tonar bort och byter färg när man trycker på en tangent, precis som resten av postern. \n\n// Nytt för mig i koden: ett eget objekt per gnista med livslängd (life), pmouseX/pmouseY för att mäta musens hastighet, dist(), constrain(), floor(), setAlpha() för genomskinlighet, samt att listan loopas baklänges och splice() tar bort döda gnistor. \n\n// Mycket av gnistfunktionen var svårt att förstå innan jag sökte upp hur delarna fungerar. Nu förstår jag ungefär hur de samverkar: varje gnista är ett objekt med position, hastighet, storlek och livslängd, och livslängden avgör när den tas bort. pmouseX och pmouseY sparar musens förra position, så att dist() kan räkna ut hur snabbt musen rör sig och därmed hur många gnistor som ska skapas. floor() avrundar nedåt till ett heltal, och setAlpha() styr genomskinligheten så att gnistorna tonar bort. Loopen går baklänges eftersom splice() ändrar arrayens index när en gnista tas bort, och bakifrån minskar risken att någon hoppas över.\n\n// Jag har förstått att gnistfunktionen inte bara handlar om att rita små cirklar, utan också om att uppdatera rörelse, kontrollera livslängd och ta bort det som inte behövs, alltså ett enkelt partikelsystem. Jag behöver fortfarande mer övning för att kunna skriva något liknande från grunden, och just nu behöver jag stöd av AI eller uppslagsverk.\n\n// MIN BEDÖMNING AV STEG 3 (DESIGNKRITIK):\n\n// Passar gnistorna i designen?\n\n// Jag tycker att gnistorna tillför en intressant detalj eftersom de gör bilden mindre statisk och ger den en känsla av kaotisk energi. Partiklarna passar ihop med neonfärgerna och den elektroniska rave-stilen. Jag gillar särskilt kontrasten mellan ringarnas regelbundna former och gnistornas oförutsägbara rörelse, eftersom effekterna då kompletterar varandra istället för att alla rör sig på samma sätt.\n\n// Interaktiviteten\n\n// Att låta musens hastighet styra antalet gnistor är en intressant lösning. Användaren kan själv experimentera och få olika resultat beroende på hur musen rörs, vilket känns mer aktivt än om gnistorna dök upp automatiskt med samma intensitet hela tiden. Effekten blir ganska diskret vid långsamma rörelser och intensiv vid snabba. Jag gillar det, men det behöver balanseras så att gnistorna syns tydligt utan att ta över affischen.\n\n// Hur det kopplar till originalet från vecka 42\n\n// Originalets grundidé är fortfarande tydlig: en interaktiv poster med neonfärger, geometriska former och en glitchig stil, och alla ursprungliga funktioner finns kvar. Både ringarna och gnistorna är utökningar inom samma visuella värld, och de använder mina befintliga färgfunktioner, så att allt följer färgbytet. Förändringen känns därför som en vidareutveckling snarare än en ny design, och visar hur en liten programmeringsändring kan påverka hela upplevelsen.\n\n// EGNA JUSTERINGAR EFTER TESTNING\n\n// Efter att AI:n lade till neongnistor testade jag effekten och ändrade storleken från random(2, 6) till random(6, 12). De större gnistorna förstärker affischens rave- och psykedeliska uttryck och gör partiklarna mer framträdande.\n\n// Jag ökade även ringarnas hastighet genom att ändra det högsta värdet från 4 till 8. Då expanderar ringarna snabbare när musen rör sig mot den nedre delen av canvasen, vilket ger ett intensivare uttryck.\n\n// Till sist minskade jag antalet ringar från 16 till 14, för att göra effekten mindre tät så att ringarna inte konkurrerar lika mycket med texten och gnistorna. Den slutliga versionen använder alltså 14 ringar och 0,5–8 pixlar per bildruta, medan AI:ns första version av steg 2 hade 16 ringar och 0,5–4 pixlar per bildruta.\n\n// LÄSBARHET OCH BALANS\n\n// Min största kritik av helheten är att texten längst ned ibland blir svårläst när ringar, cirklar och gnistor överlappar den. Samtidigt är affischen interaktiv, och användaren kan flytta musen för att påverka var effekterna hamnar. Det skapar en balans mellan en intensiv rave-estetik och användarens eget inflytande, men effekterna kan ibland konkurrera med texten.\n\n// Jag har valt att behålla effekterna eftersom de är en viktig del av affischens identitet, och eftersom uppgiften bestod av tre avgränsade steg valde jag att inte göra fler ändringar. Om jag fortsatte utveckla postern skulle jag testa den på andra personer för att se om texten är lätt att läsa, och vid behov prova en diskret mörk bakgrund bakom texten utan att ta bort rave-känslan.\n\n//======================================================================\n\n// ---------- KONSTANTER ----------\nconst START_CIRCLES = 30;\nconst MAX_CIRCLES = 150;\nconst EXPLOSION_SIZE = 10;\nconst MAX_SPARKS = 200;\n\n// ---------- VARIABLER ----------\nlet bgImg;\nlet circles = [];\nlet sparks = [];\nlet usePink = true;\nlet flash = 0;\n\n// ---------- SETUP ----------\nasync function setup() {\n  bgImg = await loadImage('bg.png');\n  createCanvas(600, 800);\n  textAlign(CENTER, CENTER);\n\n  for (let i = 0; i < START_CIRCLES; i++) {\n    circles.push(makeCircle(random(width), random(height)));\n  }\n}\n\n// ---------- DRAW ----------\nfunction draw() {\n  background(0);\n\n  // Bildens synlighet styrs av musens y-position\n  tint(255, map(mouseY, 0, height, 60, 200));\n  image(bgImg, 0, 0, width, height);\n  noTint();\n\n  drawSquares();\n  drawRings();\n  drawCircles();\n  drawSparks();\n  drawGlitchBars();\n  drawScanlines();\n  drawFlash();\n  drawText();\n}\n\n// ---------- HJÄLPFUNKTIONER ----------\n// STEG 1: tillagd av AI vid refaktoreringen (se reflektionen överst)\nfunction makeCircle(x, y) {\n  return { x: x, y: y, size: random(10, 50) };\n}\n\nfunction neonColor() {\n  return usePink ? color(255, 0, 200) : color(0, 255, 100);\n}\n\nfunction contrastColor() {\n  return usePink ? color(0, 255, 240) : color(255, 0, 200);\n}\n\n// ---------- ROTERANDE FYRKANTER ----------\nfunction drawSquares() {\n  push();\n  translate(mouseX, mouseY);\n  rectMode(CENTER);\n  noFill();\n  strokeWeight(2);\n  stroke(neonColor());\n\n  for (let i = 0; i < 8; i++) {\n    rotate(frameCount * 0.005 + 0.1);\n    rect(0, 0, 60 + i * 50, 60 + i * 50);\n  }\n  pop();\n}\n\n// ---------- RINGAR (neonportal) ----------\n// STEG 2: ändrad av AI på min begäran. Värdena (14 ringar, 0,5-8) justerade jag själv efter testning.\nfunction drawRings() {\n  noFill();\n\n  // Sparar hur långt ringarna har expanderat (finns kvar mellan bildrutorna)\n  if (drawRings.phase === undefined) {\n    drawRings.phase = 0;\n  }\n\n  // Hastighet 0,5-8 px/bildruta: längre ned = snabbare\n  // (true i slutet håller värdet inom 0,5-8 även om musen lämnar canvasen)\n  drawRings.phase += map(mouseY, 0, height, 0.5, 8, true);\n\n  // 14 ringar, jämnt fördelade mellan 0 och 700 px i diameter\n  for (let i = 0; i < 14; i++) {\n    let size = (i * (700 / 14) + drawRings.phase) % 700;\n\n    // Linjetjocklek 1-3 px: små ringar tunna, stora tjocka -> djup\n    strokeWeight(map(size, 0, 700, 1, 3));\n\n    // Växla färg med mina befintliga färgfunktioner\n    stroke(i % 2 === 0 ? neonColor() : contrastColor());\n\n    // Alltid centrerad vid musen\n    ellipse(mouseX, mouseY, size, size);\n  }\n}\n\n// ---------- CIRKLAR ----------\nfunction drawCircles() {\n  noStroke();\n  fill(contrastColor());\n\n  for (let i = 0; i < circles.length; i++) {\n    let c = circles[i];\n\n    // Dras mot musen + svänger i sidled\n    c.x += (mouseX - c.x) * 0.02;\n    c.y += (mouseY - c.y) * 0.02;\n    c.x += cos(frameCount * 0.05 + i) * 2;\n\n    // Skakar när musknappen hålls nere\n    if (mouseIsPressed) {\n      c.x += random(-5, 5);\n      c.y += random(-5, 5);\n    }\n\n    ellipse(c.x, c.y, c.size, c.size);\n  }\n}\n\n// ---------- NEON-GNISTOR ----------\n// STEG 3: AI:ns eget förslag. Storleken (6-12) justerade jag själv efter testning.\nfunction drawSparks() {\n  // Hur snabbt musen rörde sig sedan förra bildrutan\n  let speed = dist(mouseX, mouseY, pmouseX, pmouseY);\n\n  // Snabbare mus = fler nya gnistor (0-5 per bildruta)\n  let newSparks = floor(constrain(speed / 4, 0, 5));\n  for (let i = 0; i < newSparks; i++) {\n    sparks.push({\n      x: mouseX,\n      y: mouseY,\n      vx: random(-2, 2),\n      vy: random(-2, 2),\n      life: 255,\n      size: random(6, 12),\n      useContrast: random() < 0.5\n    });\n  }\n\n  // Ta bort de äldsta om det blivit för många\n  while (sparks.length > MAX_SPARKS) {\n    sparks.shift();\n  }\n\n  noStroke();\n\n  // Loopar baklänges så att borttagning med splice() inte gör att nästa element hoppas över.\n  for (let i = sparks.length - 1; i >= 0; i--) {\n    let s = sparks[i];\n\n    s.x += s.vx;\n    s.y += s.vy;\n    s.life -= 8;\n\n    // Död gnista: ta bort och gå vidare\n    if (s.life <= 0) {\n      sparks.splice(i, 1);\n      continue;\n    }\n\n    // Färgen hämtas varje bildruta så att den följer temat\n    let col = s.useContrast ? contrastColor() : neonColor();\n    col.setAlpha(s.life);\n    fill(col);\n    ellipse(s.x, s.y, s.size, s.size);\n  }\n}\n\n// ---------- GLITCH-STRECK ----------\nfunction drawGlitchBars() {\n  noStroke();\n\n  // Syns bara i ca 2% av bildrutorna\n  if (random() < 0.02) {\n    for (let i = 0; i < 3; i++) {\n      fill(255, 90);\n      rect(0, random(height), width, random(5, 25));\n    }\n  }\n}\n\n// ---------- SCANLINES ----------\nfunction drawScanlines() {\n  stroke(0, 70);\n  strokeWeight(1);\n\n  for (let y = 0; y < height; y += 4) {\n    line(0, y, width, y);\n  }\n}\n\n// ---------- BLIXT ----------\nfunction drawFlash() {\n  if (flash > 0) {\n    noStroke();\n    fill(255, flash);\n    rect(0, 0, width, height);\n    flash -= 15;\n  }\n}\n\n// ---------- TEXT ----------\nfunction drawText() {\n  let offset = map(mouseX, 0, width, -10, 10);\n  let shake = mouseIsPressed ? random(-6, 6) : 0;\n\n  textFont('Impact');\n  textSize(110 + sin(frameCount * 0.1) * 8);\n\n  // Två kopior av titeln åt varje håll = glitch-effekt\n  drawTitle(contrastColor(), width / 2 - offset, shake);\n  drawTitle(neonColor(), width / 2 + offset, -shake);\n\n  textFont('Courier New');\n  fill(255);\n  textSize(18);\n  text('EAT. SLEEP. RAVE. REPEAT.', width / 2, 730);\n  textSize(14);\n  text('Poster by Hanna Dahl Clolien', width / 2, 765);\n}\n\nfunction drawTitle(col, x, shakeY) {\n  fill(col);\n  text('ACID', x, 100 + shakeY);\n  text('VOID', x, 200 + shakeY);\n}\n\n// ---------- INPUT ----------\nfunction mousePressed() {\n  for (let i = 0; i < EXPLOSION_SIZE; i++) {\n    circles.push(makeCircle(mouseX, mouseY));\n  }\n\n  // Ta bort de äldsta om det blivit för många\n  while (circles.length > MAX_CIRCLES) {\n    circles.shift();\n  }\n}\n\nfunction keyPressed() {\n  usePink = !usePink;\n  flash = 200;\n}", "assets": {"bg.png": {"mime": "image/webp", "b64": ""}}});
